WITH filtered_payments AS (SELECT * FROM payments WHERE amount BETWEEN 1330 AND 1590 AND (amount > 1420 OR status = 'REFUNDED')), Summary AS (SELECT status, CASE WHEN amount >= 1280 THEN 'high' WHEN amount >= 660 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN status = 'SUCCESS' THEN amount ELSE 0 END) AS success_amount FROM filtered_payments GROUP BY status, CASE WHEN amount >= 1280 THEN 'high' WHEN amount >= 660 THEN 'mid' ELSE 'low' END) SELECT * FROM Summary WHERE success_amount < 47
